'use strict';
// Diagnostic preload: no changed acceptance conditions; no retries.
if (process.argv[1]?.endsWith('/assert-report-retained-evidence.cjs')) {
  const fs = require('node:fs'), path = require('node:path'), Module = require('node:module');
  const crypto = require('node:crypto');
  const events = [], original = Module._extensions['.js'];
  const hash = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
  const output = process.env.HEX_LEASE_TRACE || '/tmp/hex-lease-trace.json';
  function note(kind, data) { events.push({ sequence: events.length, kind, ...data }); }
  globalThis.__hexLeaseTrace = (kind, file, token, read) => {
    const record = { file, expectedTokenHash: hash(token), stack: new Error().stack.split('\n').slice(2, 7) };
    if (read) Object.assign(record, { readHash: read.sha256, readStamp: read.token, actualTokenHash: hash(JSON.parse(read.bytes).token), matches: JSON.parse(read.bytes).token === token });
    try {
      const bytes = fs.readFileSync(file), stat = fs.statSync(file, { bigint: true });
      record.directHash = hash(bytes); record.directTokenHash = hash(JSON.parse(bytes).token);
      record.directStamp = [stat.dev, stat.ino, stat.size, stat.mtimeNs, stat.ctimeNs].map(String).join(':');
    } catch (error) { record.directError = error.code; }
    note(kind, record);
  };
  for (const name of ['renameSync', 'unlinkSync', 'rmSync']) {
    const previous = fs[name];
    fs[name] = function(...args) {
      if (args.some(arg => typeof arg === 'string' && arg.includes('.pulse-report-locks'))) note(name, { paths: args.filter(arg => typeof arg === 'string'), stack: new Error().stack.split('\n').slice(2, 6) });
      return previous.apply(this, args);
    };
  }
  Module._extensions['.js'] = function(module, file) {
    if (!file.endsWith('/wasm/packages/cli/src/internal/report/retained.js')) return original(module, file);
    let source = fs.readFileSync(file, 'utf8');
    const edits = [
      ["atomicWrite(project.root, relative, Buffer.from(JSON.stringify({ token })));", "atomicWrite(project.root, relative, Buffer.from(JSON.stringify({ token }))); globalThis.__hexLeaseTrace('acquired', file, token);"],
      ["try { if (parseJson(readFile(project.root, relative, 4096).bytes).token === token)", "try { const read = readFile(project.root, relative, 4096); globalThis.__hexLeaseTrace('release', file, token, read); if (parseJson(read.bytes).token === token)"],
      ["release.verify = () => ensure(parseJson(readFile(project.root, relative, 4096).bytes).token === token, 'REPORT_CONCURRENT_BUILD');", "release.verify = () => { const read = readFile(project.root, relative, 4096); globalThis.__hexLeaseTrace('verify', file, token, read); ensure(parseJson(read.bytes).token === token, 'REPORT_CONCURRENT_BUILD'); };"]
    ];
    for (const [from, to] of edits) { if (!source.includes(from)) throw Error('Missing trace point'); source = source.replace(from, to); }
    module._compile(source, file);
  };
  process.on('exit', code => fs.writeFileSync(output, JSON.stringify({ code, pid: process.pid, events }, null, 2) + '\n'));
}

